import {need,object} from '../node/store.mjs';
import {readResearchHostFile,openResearchSource} from './workspace-files.mjs';
const endpoint='/api/europe-pmc';
const pathId=value=>{need(typeof value==='string'&&value.length>0&&value.length<=160&&!/[\u0000-\u001f\u007f/\\]/.test(value),'EUROPE_PMC_ID_INVALID');return encodeURIComponent(value);};
const parameters=value=>{const query=new URLSearchParams();for(const[key,item]of Object.entries(value??{}))if(item!==undefined&&item!==null)query.set(key,String(item));return query.size?'?'+query.toString():'';};
export function createEuropePmcClient({request,download,upload}={}) {
  need(typeof request==='function'&&typeof download==='function'&&typeof upload==='function','EUROPE_PMC_RESEARCH_CLIENT_REQUIRED');
  let selection=null;
  const options=value=>({...value,headers:{...(value?.headers??{}),...(selection?{'X-Europe-Pmc-Selection':selection}:{})}});
  const read=(path,input,selected)=>request(endpoint+path,input,options(selected));
  const operation=id=>'/operations/'+pathId(id);
  return {
    async list(input={}){const value=await read(parameters(input));selection=value.selection.library;return value;},
    status:()=>read('/status'),
    history:()=>read('/history'),
    query:id=>read('/queries/'+pathId(id)),
    saveQuery:input=>read('/queries',input),
    prepare:input=>read('/operations',input),
    inspect:id=>read(operation(id)),
    start:(id,input)=>read(operation(id)+'/start',input),
    stop:id=>read(operation(id)+'/stop',{}),
    seal:(id,input)=>read(operation(id)+'/seal',input),
    continueSearch:(id,input)=>read(operation(id)+'/continue',input),
    chain:id=>read(operation(id)+'/chain'),
    records:(id,input={})=>read(operation(id)+'/records'+parameters(input)),
    source:(id,index,{boundary=false}={})=>read(operation(id)+'/source'+parameters({index,descriptor:true,boundary})),
    importDocuments:(id,input)=>read(operation(id)+'/import',input),
    async importFile(id,{file,sha256,expectedPlanSha256,stopReason=null}={}) {
      const bytes=await readResearchHostFile(resolve(file),48*1024*1024,{sha256});
      const packet=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes));
      need(object(packet)&&packet.schema==='stellar-forge.europe-pmc-import.v1','EUROPE_PMC_IMPORT_PACKET_INVALID');
      need((packet.documents===undefined)!==(packet.pages===undefined),'EUROPE_PMC_ORIGINAL_IMPORT_REQUIRED');
      return read(operation(id)+'/import',{expectedPlanSha256,stopReason:packet.stopReason??stopReason,
        ...(packet.documents?{documents:packet.documents}:{pages:packet.pages})});
    },
    review:input=>read('/reviews',input),
    receive:(id,input)=>read(operation(id)+'/receive',input),
    comparison:input=>read('/comparison'+parameters(input)),
    exportEdition:(id,{file,format='edition',...selected}={})=>{
      need(['edition','ris','csv','review'].includes(format),'EUROPE_PMC_EXPORT_FORMAT_INVALID');
      return download(endpoint+operation(id)+'/files/'+format,file,options(selected));
    },
    exportSource:(id,{file,index,boundary=false,...selected}={})=>download(endpoint+operation(id)+'/source'+parameters({index,boundary}),file,options(selected)),
    exportWorkspace:input=>read('/exports',input),
    downloadWorkspace:({requestId,file,...selected})=>download(endpoint+'/exports/'+pathId(requestId),file,options(selected)),
    async restoreFile({requestId,actor,file,expectedSha256,...selected}={}) {
      const source=await openResearchSource(resolve(file),128*1024*1024,{sha256:expectedSha256});
      try{const value=await upload(endpoint+'/restore'+parameters({requestId,actor,sha256:source.sha256}),source,options(selected));
        selection=value.selected.library;return value;}
      finally{await source.close();}
    },
  };
}

// MIT — Interpret retained research metadata and the original provider's live view.
import { createHash } from 'node:crypto';
import { need, object, parseJson } from '../node/store.mjs';
import {SOURCE_BUNDLE_SCHEMA,projectSourceBundle} from './source-bundles.mjs';

export const SCHEMA = 'sf88-research-results-v1';
export const hash = bytes => createHash('sha256').update(bytes).digest('hex');
const string = value => typeof value === 'string' ? value : '';
const display = value => typeof value === 'string' ? value : JSON.stringify(value, null, 2);

export function canonicalSource(item, fallback) {
  let doi = string(item.doi).trim().replace(/^https?:\/\/(?:dx\.)?doi\.org\//i, '').replace(/^doi:\s*/i, '').toLowerCase();
  if (doi) return 'doi:' + doi;
  if (string(item.url)) {
    try { const url = new URL(item.url); url.hash = ''; return 'url:' + url.href; } catch { /* Preserve the original value below. */ }
  }
  if (string(item.id)) return 'provider:' + string(item.provider) + ':' + item.id;
  return 'occurrence:' + fallback;
}

function abstract(index) {
  if (!object(index)) return '';
  const words = [];
  for (const [word, positions] of Object.entries(index)) {
    if (!Array.isArray(positions)) continue;
    for (const position of positions) {
      if (Number.isSafeInteger(position) && position >= 0 && position < 200000) words[position] = word;
    }
  }
  return words.join(' ').trim();
}

function item(row, index, provider) {
  need(object(row), 'RESEARCH_RESULT_OBJECT_REQUIRED');
  const content = row.content ?? row.abstract ?? row.description ?? '';
  need(typeof content === 'string' || object(content) ||
    (Array.isArray(content) && content.every(object)), 'RESEARCH_CONTENT_SHAPE_INVALID');
  return {
    key: String(index), id: string(row.id), provider,
    title: string(row.title) || string(row.display_name) || 'Untitled source',
    url: string(row.url), doi: string(row.doi),
    content, snippet: string(row.description) || string(row.abstract) || display(content).slice(0, 360),
    publishedAt: string(row.publication_date) || string(row.publishedAt),
    authors: Array.isArray(row.authors) ? row.authors : [],
    citation: row.citation ?? null, references: row.references ?? null,
    metadata: row.metadata ?? {}, original: row,
  };
}

export function normalizeResponse(raw, provider = 'research') {
  // The original fatal UTF-8 parser omits one leading BOM without changing the retained input.
  const originalResponse = parseJson(typeof raw === 'string' ? Buffer.from(raw, 'utf8') : raw);
  const response = originalResponse?.schema===SOURCE_BUNDLE_SCHEMA ? projectSourceBundle(originalResponse) : originalResponse;
  need(object(response), 'RESEARCH_RESPONSE_OBJECT_REQUIRED');
  provider = String(provider).toLowerCase();
  // Valyu output is opened through its maintained entitlement-aware edition reader.
  need(provider !== 'valyu' && !(Object.hasOwn(response, 'tx_id') &&
    Object.hasOwn(response, 'total_deduction_dollars')), 'VALYU_EDITION_REFERENCE_REQUIRED');
  if (provider === 'openalex') {
    need(Array.isArray(response.results) && object(response.meta), 'OPENALEX_WORKS_RESPONSE_REQUIRED');
    const items = response.results.map((row, index) => {
      const location = row.primary_location ?? {};
      const normalized = {
        id: row.id, title: row.title || row.display_name, url: row.doi || row.id,
        doi: row.doi ?? '', content: abstract(row.abstract_inverted_index),
        publication_date: row.publication_date,
        references: row.referenced_works ?? [],
        authors: (row.authorships ?? []).map(auth => auth.author?.display_name).filter(Boolean),
        metadata: {
          type: row.type ?? null, cited_by_count: row.cited_by_count ?? null,
          open_access: row.open_access ?? null, primary_location: location,
          locations: row.locations ?? [], topics: row.topics ?? [],
        },
      };
      return { ...item(normalized, index, provider), original: row };
    });
    return {
      provider, query: string(response.query), status: 'AVAILABLE', items,
      usage: { totalResults: response.meta.count ?? items.length, page: response.meta.page ?? null },
      sourceTerms: 'OpenAlex metadata: CC0; linked full text retains its own licence.',
      warnings: [], raw: response,
    };
  }
  need(response.schema === SCHEMA && Array.isArray(response.results), 'RESEARCH_ENVELOPE_REQUIRED');
  need(typeof response.sourceTerms === 'string' && response.sourceTerms.trim().length > 0,
    'RESEARCH_SOURCE_TERMS_REQUIRED');
  const name = string(response.provider) || provider;
  return {
    provider: name, query: string(response.query), status: response.success === false ? 'PROVIDER_ERROR' :
      response.status === 'PARTIAL' ? 'PARTIAL' : 'AVAILABLE',
    items: response.results.map((row, index) => item(row, index, name)),
    usage: object(response.usage) ? response.usage : {},
    sourceTerms: response.sourceTerms, warnings: Array.isArray(response.warnings) ? response.warnings : [],
    error: response.error ?? null, raw: originalResponse,
  };
}

export function normalizeProjection(value, provider) {
  need(object(value), 'EDITION_VIEW_INVALID');
  const status = string(value.status) || 'UNAVAILABLE';
  const live = status === 'AVAILABLE' || status === 'PARTIAL';
  const sourceItems = live && Array.isArray(value.items) ? value.items : [];
  const items = sourceItems.map((row, index) => {
    const normalized = item(row, index, provider);
    if (Object.hasOwn(row, 'original')) normalized.original = row.original;
    normalized.key = typeof row.key === 'string' || typeof row.key === 'number' ? String(row.key) : String(index);
    need(normalized.key.length > 0 && normalized.key.length <= 512, 'EDITION_OCCURRENCE_KEY_INVALID');
    return normalized;
  });
  need(new Set(items.map(row => row.key)).size === items.length, 'EDITION_OCCURRENCE_KEY_DUPLICATE');
  return {
    provider, status, items, usage: object(value.usage) ? value.usage : {},
    warnings: Array.isArray(value.warnings) ? value.warnings : [],
    error: value.error ?? null, availableUntil: value.availableUntil ?? null,
    retention: value.retention ?? 'ORIGINAL_EDITION_ACCESS',
  };
}

export function sourceView(editions, projections, selections) {
  const groups = new Map();
  for (const edition of editions) {
    const projection = projections.get(edition.id);
    for (const row of projection?.items ?? []) {
      const occurrenceId = 'o_' + hash(edition.id + '\n' + row.key);
      const key = canonicalSource(row, occurrenceId);
      const sourceId = 's_' + hash(key);
      let group = groups.get(sourceId);
      if (!group) {
        group = { id: sourceId, title: row.title, url: row.url, doi: row.doi,
          snippet: row.snippet, content: row.content, provider: row.provider,
          publishedAt: row.publishedAt, metadata: row.metadata, authors: row.authors,
          citations: [], variants: [], selected: false, note: '', classification: 'unreviewed',
          occurrenceIds: [], retained: true };
        groups.set(sourceId, group);
      }
      const contentDigest = hash(JSON.stringify(row.content));
      const citation = {
        occurrenceId, editionId: edition.id, questionId: edition.questionId, key: row.key,
        title: row.title, url: row.url, doi: row.doi, contentDigest, provider: row.provider,
        publishedAt: row.publishedAt, citation: row.citation, references: row.references,
        original: row.original,
        retained: edition.mode === 'retained',
      };
      group.citations.push(citation); group.occurrenceIds.push(occurrenceId);
      group.retained &&= edition.mode === 'retained';
      if (!group.variants.some(variant => variant.contentDigest === contentDigest)) {
        group.variants.push({ contentDigest, content: row.content, editionId: edition.id,
          title: row.title, url: row.url, original: row.original });
      }
      // The newest edition supplies the displayed revision, with older variants kept above.
      Object.assign(group, { title: row.title, url: row.url, snippet: row.snippet, content: row.content,
        publishedAt: row.publishedAt, metadata: row.metadata, authors: row.authors });
      const selection = selections.find(entry => entry.occurrenceId === occurrenceId);
      if (selection) {
        group.selected ||= selection.selected;
        if (selection.note && !group.note.split('\n\n').includes(selection.note)) {
          group.note = [group.note, selection.note].filter(Boolean).join('\n\n');
        }
        if (selection.classification !== 'unreviewed') group.classification = selection.classification;
      }
    }
  }
  return [...groups.values()];
}

export function compareViews(before, after) {
  const left = new Map(before.sources.map(source => [source.id, source]));
  const right = new Map(after.sources.map(source => [source.id, source]));
  const added = after.sources.filter(source => !left.has(source.id));
  const removed = before.sources.filter(source => !right.has(source.id));
  const changed = [];
  for (const [id, source] of right) {
    const old = left.get(id);
    if (!old) continue;
    const changes = [];
    if (hash(JSON.stringify(old.content)) !== hash(JSON.stringify(source.content))) changes.push('content');
    if (old.citations.length !== source.citations.length) changes.push('citations');
    if (old.selected !== source.selected) changes.push('selection');
    if (old.note !== source.note) changes.push('note');
    if (old.classification !== source.classification) changes.push('classification');
    if (changes.length) changed.push({ id, title: source.title, changes, before: old, after: source });
  }
  const questionMap = new Map(before.questions.map(question => [question.id, question]));
  const questions = after.questions.filter(question => JSON.stringify(questionMap.get(question.id)) !== JSON.stringify(question));
  const leftFindings = new Map(before.findings.map(finding => [finding.id, finding]));
  const rightFindings = new Map(after.findings.map(finding => [finding.id, finding]));
  const findingFields = ['questionId', 'title', 'text', 'occurrenceIds', 'sourceIds', 'unavailableSources'];
  const findings = {
    added: after.findings.filter(finding => !leftFindings.has(finding.id)),
    removed: before.findings.filter(finding => !rightFindings.has(finding.id)),
    changed: after.findings.flatMap(finding => {
      const old = leftFindings.get(finding.id);
      if (!old) return [];
      const changes = findingFields.filter(key => JSON.stringify(old[key]) !== JSON.stringify(finding[key]));
      return changes.length ? [{ id: finding.id, changes, before: old, after: finding }] : [];
    }),
  };
  return {
    before: before.revision, after: after.revision, added, removed, changed, questions, findings,
    editions: after.editions.filter(edition => !before.editions.some(old => old.id === edition.id)),
    availability: after.editions.filter(edition => !['AVAILABLE', 'PARTIAL'].includes(edition.status)),
  };
}

// MIT. Portable identity of an original completed Object Buyer file.
import {basename,isAbsolute,resolve} from 'node:path';
import {need,object,digest} from '../node/store.mjs';

export const RESEARCH_OBJECT_REFERENCE = 'stellar-forge.research-object-acquisition.v1';
const HEX = /^[a-f0-9]{64}$/;
const SESSION = /^[A-Za-z0-9][A-Za-z0-9_-]{0,63}$/;
const UUID = /^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/;
const FIELDS = ['schema','workspaceId','session','sessionId','sourceIntentId',
  'configurationSha256','sourceUrl','snapshot','deliveryMode','bytes','sha256',
  'chunkCount','chunkManifestSha256','filename','contentType','objectId','descriptionSha256'];
const text = (value,max) => typeof value === 'string' && value.trim().length > 0 &&
  Buffer.byteLength(value) <= max && !/[\0-\x1f\x7f]/.test(value);

export function researchObjectWorkspaceId(directory) {
  need(typeof directory==='string'&&isAbsolute(directory)&&resolve(directory)===directory&&
    directory!=='/'&&!directory.includes('\0'),'RESEARCH_OBJECT_ABSOLUTE_PATH_REQUIRED');
  return 'object_'+digest(Buffer.from(directory));
}

/** Validate retained provenance; it describes acquisition identity, not a new payment claim. */
export function validateResearchObjectReference(value,input = null) {
  need(object(value) && value.schema === RESEARCH_OBJECT_REFERENCE &&
    Object.keys(value).length === FIELDS.length && Object.keys(value).every(key => FIELDS.includes(key)),
  'RESEARCH_OBJECT_REFERENCE_INVALID');
  need(text(value.workspaceId,128) && SESSION.test(value.session ?? '') &&
    UUID.test(value.sessionId ?? '') && text(value.sourceIntentId,240),
  'RESEARCH_OBJECT_IDENTITY_INVALID');
  for (const field of ['configurationSha256','snapshot','sha256','chunkManifestSha256'])
    need(HEX.test(value[field] ?? ''),'RESEARCH_OBJECT_DIGEST_INVALID');
  let url;
  try { url = new URL(value.sourceUrl); } catch {}
  need(url && url.protocol === 'https:' && !url.username && !url.password && !url.hash,
    'RESEARCH_OBJECT_SOURCE_URL_INVALID');
  need(['whole','chunks'].includes(value.deliveryMode) &&
    Number.isSafeInteger(value.bytes) && value.bytes >= 0 &&
    Number.isSafeInteger(value.chunkCount) && value.chunkCount > 0,
  'RESEARCH_OBJECT_DELIVERY_INVALID');
  need(text(value.filename,512) && !/[\\/]/.test(value.filename) &&
    !['.','..'].includes(value.filename) && text(value.contentType,256) &&
    /^[A-Za-z0-9!#$&^_.+-]+\/[A-Za-z0-9!#$&^_.+-]+(?:;[ -~]+)?$/.test(value.contentType),
  'RESEARCH_OBJECT_FILE_METADATA_INVALID');
  need((value.objectId === null || text(value.objectId,160)) &&
    (value.descriptionSha256 === null || HEX.test(value.descriptionSha256)),
  'RESEARCH_OBJECT_DESCRIPTION_INVALID');
  if (input !== null) need(object(input) &&
    ['filename','contentType','bytes','sha256'].every(key => input[key] === value[key]),
  'RESEARCH_OBJECT_INPUT_BINDING_CHANGED');
  return structuredClone(value);
}

export function researchObjectReference(delivery,{workspaceId,session} = {}) {
  const report = delivery?.report?.native, assembly = delivery?.assembly;
  need(report?.status === 'COMPLETE' && assembly &&
    ['SAVED','RECORDED'].includes(assembly.status) &&
    assembly.sessionId === report.sessionId &&
    assembly.configurationSha256 === report.configurationSha256 &&
    assembly.snapshot === report.expectedSnapshot && assembly.bytes === report.bytes &&
    assembly.sha256 === report.objectSha256 && assembly.chunkCount === report.chunkCount,
  'RESEARCH_ORIGINAL_OBJECT_DELIVERY_REQUIRED');
  return validateResearchObjectReference({
    schema:RESEARCH_OBJECT_REFERENCE,workspaceId,session,sessionId:report.sessionId,
    sourceIntentId:report.sourceIntentId,configurationSha256:report.configurationSha256,
    sourceUrl:report.sourceUrl,snapshot:report.expectedSnapshot,
    deliveryMode:report.deliveryMode ?? 'chunks',bytes:assembly.bytes,sha256:assembly.sha256,
    chunkCount:assembly.chunkCount,chunkManifestSha256:assembly.chunkManifestSha256,
    filename:basename(assembly.destination),contentType:report.expectedContentType ?? 'application/octet-stream',
    objectId:report.selection?.objectId ?? null,
    descriptionSha256:report.selection?.descriptionSha256 ?? null,
  });
}

// MIT — Stream the original portable dossier JSON through files and HTTP.
import { constants } from 'node:fs';
import { open, link, unlink } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { createHash, randomUUID } from 'node:crypto';
import { Readable } from 'node:stream';
import { createGunzip, createGzip } from 'node:zlib';
import { absolute, need, BuyerError, syncDirectory } from '../node/store.mjs';

export const PORTABLE_LIMIT = 256 * 1024 * 1024;
const VERSION_LIMIT = 8 * 1024 * 1024;
const BLOB_RECORD_LIMIT = Math.ceil(64 * 1024 * 1024 / 3) * 4 + 65536;

function transform(source, codec) {
  source.once('error', error => codec.destroy(error));
  codec.once('close', () => source.destroy());
  return source.pipe(codec);
}

async function decoded(source) {
  need(source && typeof source[Symbol.asyncIterator] === 'function', 'PORTABLE_STREAM_REQUIRED');
  const iterator = source[Symbol.asyncIterator]();
  const first = [];
  let prefixBytes = 0;
  while (prefixBytes < 2) {
    const next = await iterator.next();
    if (next.done) break;
    need(next.value instanceof Uint8Array, 'PORTABLE_STREAM_REQUIRED');
    if (!next.value.length) continue;
    const part = Buffer.from(next.value);
    first.push(part); prefixBytes += part.length;
  }
  const prefix = Buffer.concat(first);
  const stream = Readable.from((async function* () {
    let size = prefix.length;
    try {
      need(size <= PORTABLE_LIMIT, 'PORTABLE_SIZE_LIMIT');
      if (prefix.length) yield prefix;
      while (true) {
        const next = await iterator.next();
        if (next.done) break;
        need(next.value instanceof Uint8Array, 'PORTABLE_STREAM_REQUIRED');
        size += next.value.length;
        need(size <= PORTABLE_LIMIT, 'PORTABLE_SIZE_LIMIT');
        yield next.value;
      }
    } finally { await iterator.return?.(); }
  })());
  return prefix[0] === 0x1f && prefix[1] === 0x8b ? transform(stream, createGunzip()) : stream;
}

class JsonCursor {
  constructor(stream) {
    this.iterator = stream[Symbol.asyncIterator]();
    this.decoder = new TextDecoder('utf-8', {fatal: true});
    this.buffer = ''; this.position = 0; this.finished = false; this.bytes = 0;
  }
  async fill() {
    while (this.position >= this.buffer.length && !this.finished) {
      const next = await this.iterator.next();
      this.position = 0;
      if (next.done) {
        this.finished = true; this.buffer = this.decoder.decode();
      } else {
        this.bytes += next.value.length;
        need(this.bytes <= PORTABLE_LIMIT, 'PORTABLE_SIZE_LIMIT');
        this.buffer = this.decoder.decode(next.value, {stream: true});
      }
    }
    return this.position < this.buffer.length;
  }
  async space() {
    while (await this.fill()) {
      while (this.position < this.buffer.length && /[ \t\r\n]/.test(this.buffer[this.position])) this.position++;
      if (this.position < this.buffer.length) return;
    }
  }
  async peek() { await this.space(); return this.buffer[this.position] ?? null; }
  async expect(character) {
    need(await this.peek() === character, 'PORTABLE_JSON_INVALID');
    this.position++;
  }
  async value(limit) {
    await this.space();
    const first = this.buffer[this.position];
    need(first !== undefined && !',]}:'.includes(first), 'PORTABLE_JSON_INVALID');
    const container = first === '{' || first === '[';
    const scalarString = first === '"';
    const parts = [];
    let depth = 0, quoted = false, escaped = false, complete = false, bytes = 0;
    while (await this.fill()) {
      const start = this.position;
      while (this.position < this.buffer.length) {
        const character = this.buffer[this.position];
        if (!container && !scalarString && /[ \t\r\n,\]}]/.test(character)) { complete = true; break; }
        this.position++;
        if (quoted) {
          if (escaped) escaped = false;
          else if (character === '\\') escaped = true;
          else if (character === '"') {
            quoted = false;
            if (scalarString && depth === 0) { complete = true; break; }
          }
        } else if (character === '"') quoted = true;
        else if (character === '{' || character === '[') depth++;
        else if (character === '}' || character === ']') {
          depth--;
          if (container && depth === 0) { complete = true; break; }
        }
      }
      const part = this.buffer.slice(start, this.position);
      bytes += Buffer.byteLength(part); need(bytes <= limit, 'PORTABLE_RECORD_SIZE_LIMIT');
      parts.push(part);
      if (complete) break;
    }
    need(complete || (!container && !scalarString && !quoted && parts.length), 'PORTABLE_TRUNCATED');
    try { return JSON.parse(parts.join('')); }
    catch { throw new BuyerError('PORTABLE_JSON_INVALID'); }
  }
  async close() { await this.iterator.return?.(); }
}

// Top-level fields may be in any order. Each original revision/blob is yielded
// alone; the original v1 wire schema and its exact source bytes remain intact.
export async function* portableEntries(source) {
  const cursor = new JsonCursor(await decoded(source));
  const seen = new Set();
  try {
    await cursor.expect('{');
    if (await cursor.peek() !== '}') {
      while (true) {
        const key = await cursor.value(1024);
        need(typeof key === 'string' && !seen.has(key), 'PORTABLE_FIELD_INVALID');
        seen.add(key); await cursor.expect(':');
        if (key === 'versions' || key === 'blobs') {
          await cursor.expect('[');
          let index = 0;
          if (await cursor.peek() !== ']') {
            while (true) {
              const value = await cursor.value(key === 'versions' ? VERSION_LIMIT : BLOB_RECORD_LIMIT);
              yield {kind: key, index: index++, value};
              const next = await cursor.peek();
              if (next === ']') break;
              await cursor.expect(',');
            }
          }
          await cursor.expect(']');
          yield {kind: 'array', key, count: index};
        } else {
          yield {kind: 'field', key, value: await cursor.value(65536)};
        }
        if (await cursor.peek() === '}') break;
        await cursor.expect(',');
      }
    }
    await cursor.expect('}');
