      ['operator.json', configuredBytes], ['policy.json', json(policy)],
      ['operator-keys.json', json({schema:SCHEMA, keys:keySet.values})], ['signer.mjs', signerSource],
      ...(ticket ? [['operation-ticket.json', ticket.sourceBytes]] : []),
