}

/** Review never opens the operator-key file or loads the signer/SDK. */
export async function openWorkspace(args, { execute = false, accounting = false,
  environment = process.env, storageDirectory } = {}) {
  need(typeof execute === 'boolean' && typeof accounting === 'boolean' && !(execute && accounting),
    'WORKSPACE_ONE_OPERATION_MODE_REQUIRED');
  need(process.platform !== 'win32', 'WORKSPACE_POSIX_OPERATOR_REQUIRED');
  const opt = options(args, ['--dir']);
  const directory = resolve(abs(opt['--dir'], 'WORKSPACE_PATH_NOT_ABSOLUTE'));
  // Recovery reviews an authenticated staged copy against its ORIGINAL paths.
  // It never relocates those identities or permits execution from staged bytes.
  need(storageDirectory===undefined||!execute,'WORKSPACE_STAGED_REVIEW_ONLY');
  const storage=storageDirectory===undefined?directory:
    resolve(abs(storageDirectory,'WORKSPACE_PATH_NOT_ABSOLUTE'));
  await privateDirectory(storage);
  const manifest = await privateJson(join(storage, 'workspace.json'));
  need(manifest.schema === SCHEMA && manifest.directory === directory &&
    manifest.config === 'operator.json' && manifest.keys === 'operator-keys.json',
    'WORKSPACE_MANIFEST_INVALID');
  const configPath = join(storage, manifest.config);
  await privateJson(configPath);
  const cfg = await config(configPath);
  const {op, owner, transport} = execution(cfg);
  need(Object.hasOwn(NETWORKS, op.expect.network) && op.expect.network === manifest.network &&
    cfg.trustedPayer === manifest.payer &&
    owner.policy === join(directory, 'policy.json') && owner.ledger === join(directory, 'reservations.sqlite') &&
    cfg.signerModule === join(directory, 'signer.mjs') && cfg.evidenceDir === join(directory, 'evidence'),
    'WORKSPACE_CONFIG_BINDING_CHANGED');
  need(JSON.stringify(transport) === JSON.stringify(buyerTransport({
    operation:cfg.operation, buyerTransport:manifest.buyerTransport,
  })), 'WORKSPACE_TRANSPORT_BINDING_CHANGED');
  need(schemaObject(manifest.signer) && manifest.signer.network === op.expect.network &&
    manifest.signer.asset === op.expect.asset && manifest.signer.payTo === op.expect.payTo &&
    manifest.signer.expectedPayer === cfg.trustedPayer &&
    (manifest.signer.paymentFlow ?? 'authorization') === (op.expect.paymentFlow ?? 'authorization') &&
    BigInt(amount(op.expect.maxAtomic, 'WORKSPACE_SINGLE_AMOUNT_INVALID')) <=
      BigInt(amount(manifest.signer.maxAtomic, 'WORKSPACE_SIGNER_CAP_INVALID')),
    'WORKSPACE_SIGNER_BINDING_CHANGED');
  await privateDirectory(join(storage,'evidence'));
  let operatorEnvironment;
  if (execute || accounting) {
    // Surface missing local setup before an inbox attempt or SF36 reservation.
    // Accounting reopens the original journal keys without requiring a wallet,
    // importing its provider or constructing a signer after the purchase.
    if (execute) {
      if (transport !== null) resolveBuyerProxy(transport, environment);
      const {checkNativeSignerPrerequisites} = await import('./native-signer.mjs');
      await checkNativeSignerPrerequisites({...manifest.signer, environment});
    }
    const stored = await privateJson(join(storage, manifest.keys), 16384);
    need(stored.schema === SCHEMA && schemaObject(stored.keys) &&
      Object.keys(stored.keys).length === KEY_NAMES.length, 'WORKSPACE_KEY_FILE_INVALID');
    // The three journal keys come from the original private workspace. Only
    // execution receives SF81's validated, ephemeral host approval transport;
    // it is never read from the manifest or written into operator-keys.json.
    operatorEnvironment = {...keys(stored.keys).values,
      ...(execute ? operatorApprovalEnvironment(environment) : {})};
  }
  return {config:cfg, configPath, manifest, operatorEnvironment};
}

/** Review the original workspace plus package/source availability, without custody. */
export async function diagnoseWorkspace(args, {environment = process.env} = {}) {
  const workspace = await openWorkspace(args);
  const {manifest} = workspace;
  const {inspectNativeSignerRuntime, inspectSignerProvider, validateNativeSignerConfiguration} =
    await import('./native-signer.mjs');
  const checks = [];
  let sdk = null;
  const code = error => /^[A-Z0-9_]{1,120}$/.test(error?.code ?? '')
    ? error.code : 'WORKSPACE_RUNTIME_UNAVAILABLE';
  const pins = validateNativeSignerConfiguration(manifest.signer);
  const transport = buyerTransport(workspace.config);
  const browserSelected = environment.SF81_APPROVAL_SOCKET !== undefined ||
    environment.SF81_APPROVAL_TOKEN !== undefined;
  const approvalCheck = browserSelected ? 'operator-browser' : 'operator-terminal';
  try {
    await checkOperatorChannel(workspace.config.operation.intentId, {environment});
    checks.push({check:approvalCheck, status:'AVAILABLE'});
  } catch (error) {
    checks.push({check:approvalCheck, status:'UNAVAILABLE', code:code(error)});
  }
  if (transport !== null) {
    try {
      resolveBuyerProxy(transport, environment);
      checks.push({check:'merchant-proxy', status:'VALIDATED',
        ...(transport.proxyEnv === undefined ? {} : {name:transport.proxyEnv})});
    } catch (error) {
      checks.push({check:'merchant-proxy', status:'UNAVAILABLE', code:code(error),
        ...(transport.proxyEnv === undefined ? {} : {name:transport.proxyEnv})});
    }
  }
  try {
    sdk = await inspectNativeSignerRuntime(pins.network);
    checks.push({check:'official-sdk', status:'AVAILABLE'});
  } catch (error) { checks.push({check:'official-sdk', status:'UNAVAILABLE', code:code(error)}); }
  const provider = manifest.signer.signerProvider;
  if (provider !== undefined) {
    try {
      await inspectSignerProvider(provider);
      checks.push({check:'signer-provider', status:'PRESENT_NOT_IMPORTED', filename:basename(provider)});
    } catch (error) {
      checks.push({check:'signer-provider', status:'UNAVAILABLE', code:code(error)});
    }
  } else {
    const name = manifest.signer.secretEnv ?? 'STELLAR_SECRET';
    checks.push({check:'key-environment', name,
      status:Object.hasOwn(environment, name) ? 'PRESENT_NOT_LOADED' : 'MISSING'});
  }
  const ready = checks.every(check => !['UNAVAILABLE','MISSING'].includes(check.status));
  return {mode:'OPERATOR_WORKSPACE_DIAGNOSTICS', status:ready ? 'READY_TO_EXECUTE' : 'SETUP_REQUIRED',
    directory:manifest.directory, network:pins.network, payer:pins.expectedPayer,
    signerSource:provider === undefined ? 'ENVIRONMENT' : 'TRUSTED_SEP43_PROVIDER',
    rpcOrigin:new URL(pins.rpcUrl).origin, buyerTransport:buyerTransport(workspace.config),
    requestTimeoutMs:requestTimeoutMs(workspace.config), sdk, checks,
    next:ready ? 'Review the operation, then use --execute-workspace for original operator approval.' :
      'Resolve the listed runtime requirements and diagnose this same workspace again.'};
}

// MIT. Live request admission for actual SF30/SF61 imported seller offers.
// Reuses the exact original SF25 Draft 2020-12 validator; never touches payment.
import { validateBazaarExtension } from '../../../stellar-forge/payment-auto-catalog/schema-validation.mjs';
import { supportsSellerMethod } from '../sf30-seller-sdk/http-methods.mjs';
import { decodeQueryParameters, validateQuerySerialization } from '../sf30-seller-sdk/query-parameters.mjs';

const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const own = (value, key) => Object.hasOwn(value, key);
const rejected = (code = 'LIVE_REQUEST_SCHEMA_REJECTED', issues = []) => ({
  status: 422,
  body: { error: code, ...(issues.length ? { issues: issues.slice(0, 5) } : {}) },
});


/** Construct one trusted admission callback per ORIGINAL imported offer.
 *
 * At runtime the SF30 resource router has already selected method/path and
 * decoded pathParams. It invokes this callback only in NATIVE_X402 mode before
 * processHTTPRequest, never during challenge-only metadata display.
 */
export function createLiveRequestAdmission(offer) {
  const extension = offer?.extensions?.bazaar;
  const verification = validateBazaarExtension(extension);
  if (!verification.ok) throw new TypeError('Original imported Bazaar schema is invalid: ' + verification.reason);
  const reference = extension.info?.input;
  const schemaInput = extension.schema?.properties?.input;
  if (!object(reference) || reference.type !== 'http' ||
      !supportsSellerMethod(reference.method) ||
      !object(schemaInput) || !object(schemaInput.properties)) {
    throw new TypeError('A supported SF30 HTTP Bazaar offer is required');
  }
  const properties = schemaInput.properties;
  const querySchema = properties.queryParams;
  const querySerialization = structuredClone(extension.querySerialization);
  validateQuerySerialization(querySchema, querySerialization);
  const pathSchema = properties.pathParams;
  const bodySchema = properties.body;
  // A genuine imported schema, not an advertiser-supplied "required" guess.
  const method = reference.method;
  const originalInfo = structuredClone(extension.info);
  const originalSchema = structuredClone(extension.schema);

  return function admitLiveRequest(context) {
    if (!object(context) || context.method !== method || context.signal?.aborted) {
      return rejected('LIVE_REQUEST_METHOD_REJECTED');
    }
    let query;
    try { query = decodeQueryParameters(context.query ?? {}, querySchema, querySerialization); }
    catch { return rejected('LIVE_QUERY_PARAMETERS_REJECTED'); }
    const input = structuredClone(originalInfo.input);
    // Strip the seller's examples; they MUST NOT satisfy actual request fields.
    delete input.queryParams;
    delete input.pathParams;
    delete input.body;
    if (querySchema) input.queryParams = query;
    if (pathSchema) {
      if (!object(context.pathParams)) return rejected('LIVE_PATH_PARAMETERS_REJECTED');
      input.pathParams = { ...context.pathParams };
    } else if (context.pathParams && Object.keys(context.pathParams).length) {
      return rejected('LIVE_PATH_PARAMETERS_REJECTED');
    }
    if (bodySchema) {
      const absent=context.bodyPresent===false||context.bodyPresent===undefined&&context.body===undefined;
      if (!absent || schemaInput.required?.includes('body')) input.body = context.body === undefined ? null : context.body;
    } else if (context.body !== undefined && context.body !== null) {
      return rejected('LIVE_BODY_NOT_DECLARED');
    }
    const check = validateBazaarExtension({
      info: { ...originalInfo, input },
      schema: originalSchema,
    });
    if (!check.ok) {
      // Exact original schema failures, but never echo input values or payload.
      const issues = (check.errors ?? []).filter(x => typeof x === 'string')
        .map(x => x.slice(0, 160));
      return rejected('LIVE_REQUEST_SCHEMA_REJECTED', issues);
    }
    return true;
  };
}

/** Convenience adapter for the exact operator-created seller-service config.
 * Export the returned function under a route's existing admit binding name.
 */
export function admissionForServiceRoute(config, id) {
  if (config?.schema !== 'stellar-forge.seller-service.v1' || !Array.isArray(config.routes)) {
    throw new TypeError('Original SF30 seller-service config required');
  }
  const routes = config.routes.filter(route => route?.id === id);
  if (routes.length !== 1 || !object(routes[0].offer)) {
    throw new TypeError('Expected exactly one original imported offer with route id ' + id);
  }
  return createLiveRequestAdmission(routes[0].offer);
}

